CREATE TABLE tree(id INTEGER PRIMARY KEY, parent INTEGER, label TEXT);
INSERT INTO tree VALUES (1,NULL,'root'),(2,1,'a'),(3,1,'b'),(4,2,'a1'),(5,2,'a2'),(6,3,'b1');
WITH RECURSIVE walk(id, label, path) AS (
  SELECT id, label, printf('%03d', id) FROM tree WHERE parent IS NULL
  UNION ALL
  SELECT t.id, t.label, w.path || '/' || printf('%03d', t.id)
  FROM tree t JOIN walk w ON t.parent = w.id
)
SELECT id, label, path FROM walk ORDER BY path;

